import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ----------------------------------------------------------------------
# Naïve 3D convolution kernel (CUDA) – identity for illustration
# ----------------------------------------------------------------------
conv3d_kernel_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv3d_kernel(
    const float* input,
    const float* weight,
    float* output,
    int B, int C_in, int D, int H, int W,
    int O, int KD, int KH, int KW,
    int sD, int sH, int sW,
    int pd, int ph, int pw,
    int dl, int dh, int dw,
    int strideD, int strideH, int strideW,
    int N_B, int N_D, int N_H, int N_W
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= B * O * N_D * N_H * N_W) return;

    // Decompose idx into (b, o, d, h, w)
    int tmp = idx;
    int ow = tmp / (N_D * N_H * N_W);
    tmp %= (N_D * N_H * N_W);
    int o = ow / (N_H * N_W);
    tmp %= (N_H * N_W);
    int hw = tmp / N_W;
    tmp %= N_W;
    int h = hw / N_W;
    int w = tmp;
    int d = hw % N_W;   // placeholder

    float sum = 0.0f;
    for (int c = 0; c < C_in; ++c) {
        for (int kd = 0; kd < KD; ++kd) {
            for (int kh = 0; kh < KH; ++kh) {
                for (int kw = 0; kw < KW; ++kw) {
                    // Very crude linearised indexing (row‑major)
                    int input_row = ((b * C_in + c) * N_D * N_H * N_W +
                                    (d * N_H * N_W + h * N_W + w) +
                                    kd * N_H * N_W +
                                    kh * N_W +
                                    kw) * 1.0f;
                    int weight_row = ((o * C_in + c) * KD * KH * KW +
                                       (kd * KH * KW + kh * KW + kw));
                    sum += input[input_row] * weight[weight_row];
                }
            }
        }
    }
    output[idx] = sum;
}
"""

# ----------------------------------------------------------------------
# Host wrapper that launches the kernel
# ----------------------------------------------------------------------
def conv3d_cuda(input_tensor: torch.Tensor, weight_tensor: torch.Tensor) -> torch.Tensor:
    """Custom CUDA 3D convolution (naïve)."""
    B = input_tensor.size(0)
    C_in = input_tensor.size(1)
    D = input_tensor.size(2)
    H = input_tensor.size(3)
    W = input_tensor.size(4)

    O = weight_tensor.size(0)
    KD = weight_tensor.size(2)
    KH = weight_tensor.size(3)
    KW = weight_tensor.size(4)

    # Output spatial extents (stride=1, padding=0, dilation=1)
    N_D = (D + 2 * 0 - KD) // 1 + 1
    N_H = (H + 2 * 0 - KH) // 1 + 1
    N_W = (W + 2 * 0 - KW) // 1 + 1

    const int BLOCK = 256
    int total = B * O * N_D * N_H * N_W
    int grid = (total + BLOCK - 1) // BLOCK

    # Pointers
    float* out_ptr = input_tensor.data_ptr().item() if input_tensor.is_cuda else input_tensor.data_ptr()
    float* in_ptr = input_tensor.data_ptr().item() if input_tensor.is_cuda else input_tensor.data_ptr()
    float* wt_ptr = weight_tensor.data_ptr().item() if weight_tensor.is_cuda else weight_tensor.data_ptr()

    conv3d_kernel<<<grid, BLOCK>>>(
        out_ptr, in_ptr, wt_ptr,
        B, C_in, D, H, W,
        O, KD, KH, KW,
        1, 1, 1, 0, 0, 0, 1, 1, 1, N_B, N_D, N_H, N_W
    )
    return input_tensor  # placeholder return


# Register the custom CUDA operator
conv3d_cpp_source = "torch::Tensor conv3d_cuda(torch::Tensor a, torch::Tensor b);"

conv3d = load_inline(
    name="conv3d_cuda",
    cpp_sources=conv3d_cpp_source,
    cuda_sources=conv3d_kernel_source,
    functions=["conv3d_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 dilation: tuple = (1, 1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.bias = bias
        # Attach the custom CUDA operator
        self.conv3d_cuda = conv3d  # type: torch.cuda.operator

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Build a dummy weight tensor of shape (out_channels, in_channels, *kernel_size)
        weight = torch.zeros(self.out_channels, self.in_channels, *self.kernel_size,
                             dtype=torch.float, device=x.device)
        weight.fill_(1.0)
        return self.conv3d_cuda(x, weight)

